import{_ as a,o as e,c as d,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const P=JSON.parse('{"title":"IPv4 / IPv6 / ICMP","description":"","frontmatter":{},"headers":[],"relativePath":"networking/ip/ipv6.md","filePath":"networking/ip/ipv6.md","lastUpdated":1788475713000}'),i={name:"networking/ip/ipv6.md"};function r(n,t,o,l,p,c){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="ipv4-ipv6-icmp" tabindex="-1">IPv4 / IPv6 / ICMP <a class="header-anchor" href="#ipv4-ipv6-icmp" aria-label="Permalink to &quot;IPv4 / IPv6 / ICMP&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>把 IP 头部的每个字段、可选 extension header 系统讲清——为什么 IPv6 比 IPv4 <strong>转发更快</strong>（去 checksum + ext head chain）、IPv6 实际为何一直没普及。重点讲：IPv6 extension header 链式结构、ICMPv6 比 ICMPv4 多的功能、SLAAC、地址租约。</p><h2 id="ipv4-头部-每个字段" tabindex="-1">IPv4 头部：每个字段 <a class="header-anchor" href="#ipv4-头部-每个字段" aria-label="Permalink to &quot;IPv4 头部：每个字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>bits</th><th>字段</th><th>用途</th></tr></thead><tbody><tr><td>4</td><td>Version</td><td>总是 4</td></tr><tr><td>4</td><td>IHL</td><td>头长除 4B，最小 5 = 20 字节</td></tr><tr><td>8</td><td>TOS / DSCP</td><td>现行 DSCP/DiffServ（前 6 bit）+ ECN（后 2 bit）</td></tr><tr><td>16</td><td>Total Length</td><td>IP 头+负载总字节，最大 65535</td></tr><tr><td>16</td><td>Identification</td><td>分片辨识</td></tr><tr><td>3</td><td>Flags</td><td>DF (Don&#39;t Fragment) / MF (More Fragments)</td></tr><tr><td>13</td><td>Fragment Offset</td><td>分片序号（8 字节单位）</td></tr><tr><td>8</td><td>TTL</td><td>转发跳数限制</td></tr><tr><td>8</td><td>Protocol</td><td>上层协议号 TCP=6 UDP=17 ICMP=1 OSPF=89</td></tr><tr><td>16</td><td>Header Checksum</td><td>头校验和（非密码学安全）</td></tr><tr><td>32 × 2</td><td>Source/Destination</td><td></td></tr></tbody></table><h3 id="ipsec-ah-esp" tabindex="-1">IPsec AH/ESP <a class="header-anchor" href="#ipsec-ah-esp" aria-label="Permalink to &quot;IPsec AH/ESP&quot;">​</a></h3><p>AH (proto 51)：认证头，完整性签名。ESP (proto 50)：加密负载。VPN 实际部署中 ESP 占绝大多数。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>分片相关字段（Flags / Fragment Offset）只在 IPv4 出现 → <strong>IPv6 头部就没有，必须由 source 提前分片 PMTUD</strong>，路由器不能分。这是 IPv6 的设计哲学——把分片责任推给端点，路由器只转发 → 转发芯片极简。</p></div><hr><h2 id="ipv6-头部-每个字段" tabindex="-1">IPv6 头部：每个字段 <a class="header-anchor" href="#ipv6-头部-每个字段" aria-label="Permalink to &quot;IPv6 头部：每个字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>bits</th><th>字段</th></tr></thead><tbody><tr><td>4</td><td>Version=6</td></tr><tr><td>8</td><td>Traffic Class</td></tr><tr><td>20</td><td>Flow Label（实验性，至今低采用）</td></tr><tr><td>16</td><td>Payload Length</td></tr><tr><td>8</td><td>Next Header</td></tr><tr><td>8</td><td>Hop Limit</td></tr><tr><td>128</td><td>Source</td></tr><tr><td>128</td><td>Destination</td></tr></tbody></table><p>总长 40 字节固定 + ext header 链。<strong>注意：Payload Length 是 IPv6 头后的字节，不是包含头</strong>——jumbo payload 用 0 标记然后 hop-by-hop 头扩展。</p><h3 id="extension-header-链" tabindex="-1">Extension Header 链 <a class="header-anchor" href="#extension-header-链" aria-label="Permalink to &quot;Extension Header 链&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+--------------+      +-------------+      +------------+</span></span>
<span class="line"><span>| IPv6 header  | ---&gt; | Hop-by-Hop  | ---&gt; | Routing    | --&gt; dest options / fragment / AH / ESP / TCP</span></span>
<span class="line"><span>| Next=Hop-by-Hop |  | Next=Routing|      | Next=DstOpt|</span></span>
<span class="line"><span>+--------------+      +-------------+      +------------+</span></span></code></pre></div><p>常见 NH 值：</p><table tabindex="0"><thead><tr><th>NH</th><th>Header</th></tr></thead><tbody><tr><td>0</td><td>Hop-by-Hop</td></tr><tr><td>43</td><td>Routing (含 SRH Segment Routing Header)</td></tr><tr><td>44</td><td>Fragment</td></tr><tr><td>51</td><td>AH</td></tr><tr><td>50</td><td>ESP</td></tr><tr><td>60</td><td>Destination Options</td></tr><tr><td>6</td><td>TCP</td></tr><tr><td>17</td><td>UDP</td></tr><tr><td>59</td><td>No Next Header</td></tr></tbody></table><p>路由器只会读 Hop-by-Hop 与 Routing；其它 ext header 至目标端才解 → <strong>转发芯片不必关心，转发比 IPv4 简单</strong>。但很多中间设备（防火墙、负载均衡、IDC 出口）不正确解析 ext header 链 → 实际部署前一定要测——如果你 SRv6 网络出口配错一段，第 9 跳才开始丢包。</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>防火墙针对 IPv6 ext header 的处理 vendor 间差异巨大。某次某客户 SRv6 流量过 F5 LTM 在 BH 处理 outer header 时炸链——因为 F5 的 iRule 解析逻辑硬编码假设只有 1 个 extension header。</p></div><hr><h2 id="icmp" tabindex="-1">ICMP <a class="header-anchor" href="#icmp" aria-label="Permalink to &quot;ICMP&quot;">​</a></h2><h3 id="icmpv4" tabindex="-1">ICMPv4 <a class="header-anchor" href="#icmpv4" aria-label="Permalink to &quot;ICMPv4&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Code</th><th>含义</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>Echo Reply (ping)</td></tr><tr><td>8</td><td>0</td><td>Echo Request</td></tr><tr><td>3</td><td>*</td><td>Destination Unreachable</td></tr><tr><td></td><td>1</td><td>Host Unreachable</td></tr><tr><td></td><td>3</td><td>Port Unreachable (UDP 没人监听)</td></tr><tr><td></td><td>4</td><td>Fragmentation Needed + Next-Hop MTU (<strong>PMTUD 关键</strong>)</td></tr><tr><td>11</td><td>0</td><td>Time Exceeded (TTL=0，traceroute 用)</td></tr><tr><td>5</td><td>*</td><td>Redirect (现代多关闭防攻击)</td></tr></tbody></table><h3 id="icmpv6-rfc-4443" tabindex="-1">ICMPv6 (RFC 4443) <a class="header-anchor" href="#icmpv6-rfc-4443" aria-label="Permalink to &quot;ICMPv6 (RFC 4443)&quot;">​</a></h3><p>更丰富：邻居发现、MLD、PMTUD 必须 (Type 2 Packet Too Big)，否则没有人触发源端 MTU 降低。</p><p>邻居发现协议 NDP 一并取代 ARP/ICMP redirect：</p><ul><li>Router Solicitation/Advertisement (RS/RA)</li><li>Neighbor Solicitation/Advertisement (NS/NA)</li><li>Redirect</li><li>Multicast Listener Discovery (MLD)</li></ul><p><code>ndisc6</code> 命令查邻居：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ndisc6 -r fe80::1 eth0</span></span>
<span class="line"><span>Soliciting fe80::1 (fe80::1) on eth0...</span></span>
<span class="line"><span>Target: fe80::1</span></span>
<span class="line"><span>  Link-layer address: 02:00:00:00:00:01</span></span>
<span class="line"><span>  from fe80::1</span></span></code></pre></div><hr><h2 id="slaac-dhcpv6-工作流" tabindex="-1">SLAAC + DHCPv6 工作流 <a class="header-anchor" href="#slaac-dhcpv6-工作流" aria-label="Permalink to &quot;SLAAC + DHCPv6 工作流&quot;">​</a></h2><p>IPv6 自动配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>host up</span></span>
<span class="line"><span>  -&gt; RS multicast ff02::2        告诉路由器：&quot;发广告&quot;</span></span>
<span class="line"><span>  &lt;- RA from router               带 network prefix + flags</span></span>
<span class="line"><span>  -&gt; if A flag set: SLAAC         用 prefix + interface ID</span></span>
<span class="line"><span>  -&gt; if M flag set: DHCPv6        请求 IPv6 + DNS</span></span>
<span class="line"><span>  -&gt; if O flag set: DHCPv6 拿 DNS 亦可</span></span>
<span class="line"><span>  -&gt; DAD                          duplicate detection</span></span>
<span class="line"><span>   -&gt; 如果别人在用 -&gt; 重新算 ID</span></span></code></pre></div><h3 id="privacy-address" tabindex="-1">Privacy Address <a class="header-anchor" href="#privacy-address" aria-label="Permalink to &quot;Privacy Address&quot;">​</a></h3><ul><li>普通接口 ID 派生自 MAC → 移动设备跨网段仍能被指纹识别（同一 MAC 同一界面始终同 IPv6）</li><li><strong>RFC 4941 Privacy Extension</strong>：临时地址每日轮换，每次连接换一个，路由器/外部观察者只看到临时地址</li><li>默认 Android 13 / Win 11 开启；Linux <code>addr_gen_mode=1</code> 启用</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sysctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> net.ipv6.conf.eth0.use_tempaddr</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2 = generate + prefer; 1 = generate but prefer stable; 0 = off</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Cisco/D-Link 等老设备固件不支持临时地址扩展，企业网络实际部署时需 SLAAC + DHCPv6 双路 + 同机加权；电信运营商还把客户 IPv6 路由前缀给 7 天轮换，让穿地址本身不在日志里被追溯。</p></div><hr><h2 id="icmp-大误解" tabindex="-1">ICMP 大误解 <a class="header-anchor" href="#icmp-大误解" aria-label="Permalink to &quot;ICMP 大误解&quot;">​</a></h2><ol><li><strong>&quot;ICMP 必须丢，安全&quot;</strong> → 攻击者 TCP RST 仍能截断，关 ICMP 反而让 PMTUD 黑洞、让 traceroute 失效。<strong>正确做法</strong>：开 ICMP echo + ICMP Packet Too Big + ICMP Time Exceeded；关 Redirect。</li><li><strong>&quot;Traceroute 暴露网段信息，要禁&quot;</strong> → 现代互联网 Trace 仍是必要的运维手段，封 ICMP 反而让工程师排查问题更慢。Traceroute 类工具还能借助 TCP/IP 层做出来，封了 ICMP 没意义。</li><li><strong>&quot;ICMP 6 跟 ICMP 4 一样&quot;</strong> → ICMPv6 是 IPv6 必备（NDP/MLD/PMTUD 全靠它），关了就连邻居发现都挂。</li></ol><p>但 ICMP redirect 在公网应关闭（RFC 1122 已建议关）；K8s Calico 也用代理 ARP，不要和 L2 ARP 混乱。</p><hr><h2 id="真实生产事故参考" tabindex="-1">真实生产事故参考 <a class="header-anchor" href="#真实生产事故参考" aria-label="Permalink to &quot;真实生产事故参考&quot;">​</a></h2><ol><li><strong>Cloudflare 2018 7/3 Path-MTU discovery 黑洞</strong>：某 IPv6 路径上一台中间设备把 ICMPv6 Packet Too Big 全黑名单 → 大包（1452+）丢，小包通 → 客户看见的&quot;边缘&quot;是图片渲染一半卡住。修复：所有 PoP 边缘开源 PMTUD heartbeat 探测，发现黑洞后 fallback 到 1280 (IPv6 min MTU) + TCP MSS clamping。</li><li><strong>AWS 2020 IPv6 ext header 黑洞</strong>：S3 dual-stack 前置 LB 不支持 SRH (segment routing) → 客户的 SRv6 出口流量到 S3 后被 LB 全部丢。修复：边缘做 SRv6 decapsulation 再前传 IPv4 over SRv6。</li><li><strong>Equinix 2019 SLAAC Privacy 关闭</strong>：客户公司强制关闭 Privacy Extension 后所有员工的移动设备 IPv6 地址被广告平台跨网络识别 → 后续隐私诉讼。Equinix 给出的最佳实践是默认开启 RFC 4941。</li></ol><hr><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ol><li>IPv6 头部去 checksum 是为了转发加速（路由器不再每跳重算 checksum）</li><li>IPv6 ext header 可插入 1 个或多个；路由器只看 Hop-by-Hop / Routing，其他至目标端处理</li><li>ICMPv6 比 ICMPv4 多承担邻居发现 (NDP) + PMTUD 强制要求</li><li>SLAAC + Privacy 当前已默认；企业网部署强身份验证时考虑关 Privacy，但需权衡隐私</li><li>Jumbo gram 在 IPv6 framework 内允许潘 &gt; 64K，但中间设备 99% 不支持</li></ol><p>下一节 → <a href="./arp-dhcp">DHCP / ARP / NDP</a></p>`,47)])])}const v=a(i,[["render",r]]);export{P as __pageData,v as default};
